def page(slug,title,read,chain,items):
 cards=''.join(f'<article class="card"><h2>{html.escape(i["title"])}</h2><div class="badges"><span class="good">fresh signal</span> <span>{html.escape(i["typ"])}</span></div><ul class="facts"><li>{i["date"]}</li><li><a href="{i["url"]}">{html.escape(i["url"])}</a></li></ul><p><b>What:</b> {html.escape(i["what"])}</p><p><b>Why it matters:</b> {html.escape(i["why"])}</p><p><b>Buildn/client use:</b> {html.escape(i["use"])}</p><p><b>Why now:</b> {html.escape(i["now"])}</p><ul class="wins"><li>Scope the smallest useful loop</li><li>Keep outputs reviewable</li><li>Measure cost and failure</li></ul><div class="call"><b>Caveat / next move:</b> {html.escape(i["caveat"])} {html.escape(i["action"])}</div></article>' for i in items)
 src=''.join(f'<li><a href="{i["url"]}">{html.escape(i["title"])}</a></li>' for i in items)
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daily Ingest — {html.escape(title)}</title>{css}</head><body><main><header><div class="word"><span class="mark"></span>Buildn</div><div class="tag">Daily Ingest Dossier · 2026-09-30</div><h1>{html.escape(title)}</h1><p class="read">{html.escape(read)}</p></header><section class="card"><h2>Signal map</h2><div class="diagram">{svg(chain)}</div></section><section><h2>Dossier</h2>{cards}</section><section class="card"><h2>Use-case matrix</h2><table class="matrix"><tr><th>Theme</th><th>Buildn OS</th><th>Client work</th><th>Agent workflows</th><th>Personal leverage</th></tr><tr><td>Foundation</td><td>Register capabilities</td><td>Readiness sprint</td><td>Context packets</td><td>Maintain source of truth</td></tr><tr><td>Control</td><td>Audit and rollback</td><td>Approval gates</td><td>Tool scopes</td><td>Review before act</td></tr><tr><td>Experiment</td><td>Telemetry</td><td>Small pilot</td><td>Contract tests</td><td>Compare outcomes</td></tr></table></section><section class="card top"><h2>Top actions</h2><ol><li>Run one bounded pilot, not a platform rewrite.</li><li>Record cost, retries, approvals, and evidence.</li><li>Pin versions and keep a reversible fallback.</li></ol></section><section class="card"><h2>Source trail</h2><ol class="sources">{src}</ol></section><footer>Static HTML · zero scripts</footer></main></body></html>'''
for slug,(title,read,chain,items) in lanes.items(): (O/(slug+'.html')).write_text(page(slug,title,read,chain,items),encoding='utf-8')
